        if ($refund !== null && (int) $refund['refund_due_amount_in_cents'] > 0) {
            flash('Objednávka stornována. Zákazníkovi vraťte ' . format_price($refund['refund_due_amount_in_cents'], $refund['refund_due_currency']));
        } else {
            flash('Objednávka stornována');
        }

        return $this->detailAction();
    }
}
